// INPUT_CONTRACT__PUBLIC_OPERATIONS_EVIDENCE
// Accept evidence array and sources from Paola track output.
// Input structure: { evidence: [], sources: [], run_context: {} }
// Pass through with validation.
if (!Array.isArray($input.all()[0].evidence)) {
  throw new Error('Input must contain evidence array');
}
return $input.all();

// FILTER_OPERATIONS_DOMAIN
// Extract evidence relevant to operations_cx domain.
const input = $input.all()[0];
const evidence = input.evidence || [];
const sources = input.sources || [];

// Keywords indicating operations/CX relevance
const opsKeywords = [
  'volunteer', 'donor', 'application', 'form', 'process', 'workflow',
  'journey', 'follow-up', 'followup', 'contact', 'email', 'phone',
  'communication', 'automation', 'crm', 'database', 'tracking',
  'onboarding', 'stakeholder', 'experience', 'customer'
];

const opsEvidence = evidence.filter(ev => {
  const claim = (ev.claim || '').toLowerCase();
  const domain = ev.domain || '';
  return domain === 'operations_cx' || 
         opsKeywords.some(kw => claim.includes(kw));
});

return [{ evidence: opsEvidence, sources: sources, run_context: input.run_context, all_evidence: evidence }];

// CLASSIFY_EVIDENCE
// Classify evidence as observable (fact), inferred, unknown, or hypothesis.
const input = $input.all()[0];
const evidence = input.evidence || [];
const classified = {};

evidence.forEach(ev => {
  const type = ev.evidence_type || 'unknown';
  if (!classified[type]) classified[type] = [];
  classified[type].push(ev);
});

return [{ 
  observable: classified.fact || [],
  inferred_signals: classified.inferred || [],
  unknowns: classified.unknown || [],
  sources: input.sources,
  run_context: input.run_context,
  all_evidence: input.all_evidence
}];

// BUILD_FINDINGS
// Construct findings from classified evidence.
const input = $input.all()[0];
const findings = [];
let findingCounter = 0;

const makeId = () => `F-${String(++findingCounter).padStart(3, '0')}`;

// Observable findings (type: fact → finding_type: observed)
input.observable.forEach(ev => {
  const claim = ev.claim || '';
  const confidence = ev.confidence || 0.7;

  // Pattern: digital entry points
  if (claim.toLowerCase().includes('application') || claim.toLowerCase().includes('form')) {
    if (claim.toLowerCase().includes('volunteer')) {
      findings.push({
        finding_id: makeId(),
        domain: 'operations_cx',
        finding: 'The organization provides a digital entry point for prospective volunteers through its website.',
        evidence_ids: [ev.evidence_id],
        finding_type: 'observed',
        confidence: Math.min(confidence, 0.9),
        requires_validation: false,
        validation_question: null
      });
    }
  }

  // Pattern: communication mechanisms
  if (claim.toLowerCase().match(/(email|phone|contact|communication|website)/)) {
    findings.push({
      finding_id: makeId(),
      domain: 'operations_cx',
      finding: `Observable communication mechanism: ${claim}`,
      evidence_ids: [ev.evidence_id],
      finding_type: 'observed',
      confidence: Math.min(confidence, 0.85),
      requires_validation: false,
      validation_question: null
    });
  }
});

// Inferred findings (multiple signals suggest pattern)
if (input.observable.length >= 2) {
  const volunteerEvidence = input.observable.filter(e => e.claim.toLowerCase().includes('volunteer'));
  if (volunteerEvidence.length >= 2) {
    findings.push({
      finding_id: makeId(),
      domain: 'operations_cx',
      finding: 'The organization has established processes for volunteer recruitment and engagement, evidenced by public volunteer channels.',
      evidence_ids: volunteerEvidence.slice(0, 2).map(e => e.evidence_id),
      finding_type: 'inferred',
      confidence: 0.65,
      requires_validation: true,
      validation_question: 'Can you describe the complete volunteer journey from initial interest to active participation?'
    });
  }
}

// Unknown findings (public signals imply hidden internal processes)
input.observable.forEach(ev => {
  const claim = ev.claim.toLowerCase();

  // Application exists → internal process is unknown
  if (claim.includes('application') || claim.includes('form')) {
    if (claim.includes('volunteer')) {
      findings.push({
        finding_id: makeId(),
        domain: 'operations_cx',
        finding: 'The internal volunteer intake and qualification process after application submission is not publicly described.',
        evidence_ids: [ev.evidence_id],
        finding_type: 'unknown',
        confidence: 0.7,
        requires_validation: true,
        validation_question: 'After a volunteer submits an application, what is the internal process for review, qualification, and onboarding?'
      });
    }
  }
});

// Generic unknowns for processes always hidden
if (input.observable.length >= 2) {
  const genericUnknowns = [
    {
      finding: 'The organization\'s internal approach to workflow automation cannot be determined from public information.',
      question: 'Are volunteer and donor workflows currently automated or managed manually?'
    },
    {
      finding: 'The organization\'s internal approach to data integration cannot be determined from public information.',
      question: 'How is stakeholder data integrated across different systems?'
    },
    {
      finding: 'The organization\'s internal approach to follow-up tracking cannot be determined from public information.',
      question: 'How does the organization track follow-up communications with stakeholders?'
    }
  ];

  genericUnknowns.forEach(u => {
    findings.push({
      finding_id: makeId(),
      domain: 'operations_cx',
      finding: u.finding,
      evidence_ids: [input.observable[0].evidence_id],
      finding_type: 'unknown',
      confidence: 0.5,
      requires_validation: true,
      validation_question: u.question
    });
  });
}

return [{ findings: findings, finding_count: findings.length }];

// VALIDATE_FINDINGS
// Verify findings comply with contract.
const input = $input.all()[0];
const findings = input.findings || [];
const errors = [];

findings.forEach((f, i) => {
  if (!f.finding_id || !f.finding_id.startsWith('F-')) {
    errors.push(`Finding[${i}]: invalid ID`);
  }
  if (f.domain !== 'operations_cx') {
    errors.push(`Finding[${i}]: domain must be operations_cx`);
  }
  if (!['observed', 'inferred', 'unknown', 'hypothesis'].includes(f.finding_type)) {
    errors.push(`Finding[${i}]: invalid finding_type`);
  }
  if (!(f.confidence >= 0 && f.confidence <= 1)) {
    errors.push(`Finding[${i}]: confidence must be 0-1`);
  }
  if (typeof f.requires_validation !== 'boolean') {
    errors.push(`Finding[${i}]: requires_validation must be boolean`);
  }
  if (f.requires_validation && !f.validation_question) {
    errors.push(`Finding[${i}]: requires_validation=true but no validation_question`);
  }
});

if (errors.length > 0) {
  throw new Error(`Validation failed: ${errors.join('; ')}`);
}

return input;

// OUTPUT_CONTRACT__OPERATIONS_CX_FINDINGS
// Return structured findings array.
const input = $input.all()[0];
return [{ findings: input.findings }];
